import type { Question } from '../../lib/types'

export const storage_cost_questions: Question[] = [
  { id: 'd4-sto-001', domain: 4, topics: ['S3', 'storage classes', 'cost tiers'], type: 'single', stem: 'S3 Standard costs $0.023/GB/month. Logs that are rarely accessed after 30 days but must be retained for 7 years. What storage class minimizes cost after 30 days?', options: [{ id: 'A', text: 'Keep in S3 Standard — simplest option' }, { id: 'B', text: 'S3 Glacier Deep Archive — $0.00099/GB/month; lowest cost for long-term retention with 12-hour retrieval time' }, { id: 'C', text: 'S3 Intelligent-Tiering' }, { id: 'D', text: 'S3 Standard-IA (Infrequent Access)' }], correct: ['B'], explanation: 'S3 Glacier Deep Archive is the cheapest S3 storage at ~$0.00099/GB/month — 95% cheaper than S3 Standard. For 7-year compliance data that\'s rarely (if ever) accessed, Deep Archive is the cost-optimal choice. 12-hour retrieval is acceptable for compliance archives.', distractors: { A: 'S3 Standard at $0.023/GB is 23x more expensive than Deep Archive — not cost-optimized.', C: 'Intelligent-Tiering adds monitoring costs for objects < 128 KB and has higher base pricing than Glacier — not optimal for known-infrequent compliance data.', D: 'S3-IA at $0.0125/GB is cheaper than Standard but 12x more expensive than Glacier Deep Archive for long-term retention.' } },
  { id: 'd4-sto-002', domain: 4, topics: ['S3', 'lifecycle policies', 'automation'], type: 'single', stem: 'Objects are uploaded to S3 Standard daily. After 30 days, access drops to near zero. After 90 days, data must be retained for compliance for 5 more years. What automates the tiering to minimize cost?', options: [{ id: 'A', text: 'Manually move objects to cheaper storage classes' }, { id: 'B', text: 'S3 Lifecycle policy — transition to S3-IA after 30 days, Glacier Flexible Retrieval after 90 days; runs automatically with no per-object management' }, { id: 'C', text: 'S3 Intelligent-Tiering (no lifecycle needed)' }, { id: 'D', text: 'Lambda function triggered on object creation' }], correct: ['B'], explanation: 'S3 Lifecycle policies automate storage class transitions based on object age. Configure transitions: Standard → S3-IA (30 days) → Glacier (90 days). Objects move automatically with no per-object management. Add expiration rules to delete objects after the compliance period.', distractors: { A: 'Manual management doesn\'t scale for millions of objects and misses objects.', C: 'Intelligent-Tiering monitors actual access and tiers accordingly — lifecycle is better when access pattern is known and predictable.', D: 'Lambda on creation can\'t handle the age-based transitions without additional scheduling complexity.' } },
  { id: 'd4-sto-003', domain: 4, topics: ['S3', 'Intelligent-Tiering', 'unknown access'], type: 'single', stem: 'A dataset has unpredictable access patterns — some objects are accessed frequently, others rarely. S3 Standard charges for all. What storage class automatically moves objects between tiers based on actual access at no retrieval charge?', options: [{ id: 'A', text: 'S3 Standard-IA (retrieval charge on access)' }, { id: 'B', text: 'S3 Intelligent-Tiering — monitors access frequency; automatically moves to cheaper tiers if not accessed; moves back to frequent tier on access; no retrieval charges' }, { id: 'C', text: 'S3 Glacier Instant Retrieval' }, { id: 'D', text: 'S3 One Zone-IA (single AZ, cheaper)' }], correct: ['B'], explanation: 'S3 Intelligent-Tiering automatically manages tiering: Frequent Access → Infrequent Access (30 days without access) → Archive Instant Access (90 days) → optional Glacier tiers. No retrieval charges. Best for data with unknown or variable access patterns.', distractors: { A: 'Standard-IA has a per-GB retrieval fee — not appropriate when access frequency is unpredictable.', C: 'Glacier Instant Retrieval is for quarterly-accessed archives — doesn\'t auto-tier from frequent to infrequent.', D: 'One Zone-IA stores in a single AZ — acceptable for easily reproducible data but provides no auto-tiering.' } },
  { id: 'd4-sto-004', domain: 4, topics: ['S3', 'Standard-IA', 'minimum size'], type: 'single', stem: 'S3 Standard-IA charges for a 128 KB minimum object size. A company stores millions of small JSON objects (1-2 KB each) in S3-IA to save money. Is this cost-effective?', options: [{ id: 'A', text: 'Yes — S3-IA is always cheaper than Standard' }, { id: 'B', text: 'No — each small object is billed as 128 KB minimum; the cost may be higher than S3 Standard for very small objects' }, { id: 'C', text: 'Yes — minimum size charges don\'t apply to JSON objects' }, { id: 'D', text: 'S3-IA has no minimum size' }], correct: ['B'], explanation: 'S3 Standard-IA, One Zone-IA, and Glacier Instant Retrieval have a 128 KB minimum object size charge. A 2 KB object is billed as 128 KB in S3-IA but only 2 KB in S3 Standard. For very small objects, S3 Standard may be cheaper. Also consider the 30-day minimum storage period.', distractors: { A: 'For small objects with the minimum size billing, S3-IA can be more expensive than S3 Standard.', C: 'The minimum size applies to all objects in S3-IA regardless of type.', D: 'S3 Standard-IA explicitly has a 128 KB minimum object size for billing purposes.' } },
  { id: 'd4-sto-005', domain: 4, topics: ['EBS', 'snapshot', 'cost optimization'], type: 'single', stem: 'An EC2 instance has EBS snapshots taken daily for 30 days. The volume is 1 TB but only 100 GB is data; the rest is empty space. How are EBS snapshots billed?', options: [{ id: 'A', text: 'Billed for the full 1 TB per snapshot' }, { id: 'B', text: 'Billed only for used blocks — first snapshot captures ~100 GB; subsequent snapshots only capture changed blocks (incremental)' }, { id: 'C', text: 'EBS snapshots are free' }, { id: 'D', text: 'Billed at $0.05/GB regardless of data' }], correct: ['B'], explanation: 'EBS snapshots are incremental and stored in S3. The first snapshot captures all used blocks (~100 GB). Subsequent daily snapshots only store blocks changed since the previous snapshot (delta). Empty blocks are never stored. Cost: $0.05/GB/month for total snapshot storage.', distractors: { A: 'EBS snapshots compress and deduplicate — only used blocks are stored, not the full volume size.', C: 'EBS snapshots have storage charges (S3 standard rates) — not free.', D: '$0.05/GB is roughly correct but applying to full volume size overstates the cost — only changed blocks are charged.' } },
  { id: 'd4-sto-006', domain: 4, topics: ['S3', 'Glacier', 'retrieval tiers'], type: 'single', stem: 'Data archived in S3 Glacier Flexible Retrieval must be accessed immediately. Standard retrieval takes 3-5 hours. What retrieval option provides access within minutes at higher cost?', options: [{ id: 'A', text: 'Bulk retrieval (5-12 hours, lowest cost)' }, { id: 'B', text: 'Expedited retrieval — 1-5 minutes; provisioned capacity ensures availability; higher per-GB retrieval cost' }, { id: 'C', text: 'Standard retrieval (3-5 hours)' }, { id: 'D', text: 'S3 Glacier doesn\'t support rapid retrieval' }], correct: ['B'], explanation: 'Glacier Flexible Retrieval tiers: Expedited (1-5 min, highest cost), Standard (3-5 hours, moderate cost), Bulk (5-12 hours, lowest cost). Purchase Provisioned Capacity units to guarantee Expedited retrieval capacity. For guaranteed rapid Glacier access, consider Glacier Instant Retrieval instead.', distractors: { A: 'Bulk retrieval is the cheapest but slowest (5-12 hours) — not immediate access.', C: 'Standard retrieval takes 3-5 hours — not immediate.', D: 'Expedited retrieval provides near-immediate access from Glacier Flexible Retrieval.' } },
  { id: 'd4-sto-007', domain: 4, topics: ['EBS', 'volume types', 'cost'], type: 'single', stem: 'An EBS volume is provisioned as io2 (16,000 IOPS, $0.125/GB + $0.065/IOPS) but the workload only uses 3,000 IOPS. What is the cost optimization?', options: [{ id: 'A', text: 'Keep io2 for headroom' }, { id: 'B', text: 'Switch to gp3 — provision exactly 3,000 IOPS for free (up to 3,000 IOPS baseline included; $0.005/IOPS above that); no per-IOPS charge below baseline' }, { id: 'C', text: 'Switch to st1 (throughput-optimized HDD)' }, { id: 'D', text: 'Reduce the volume size' }], correct: ['B'], explanation: 'gp3 provides 3,000 IOPS baseline at no extra charge (included in $0.08/GB/month). For workloads using ≤3,000 IOPS, gp3 is the most cost-effective EBS type. Switching from io2 (16,000 IOPS @ $0.065/IOPS = $1,040/month in IOPS charges) to gp3 saves significantly.', distractors: { A: 'Over-provisioned io2 wastes money — match IOPS provisioning to actual workload requirements.', C: 'st1 is for sequential large block throughput (Hadoop, streaming) — not a replacement for random IOPS workloads.', D: 'Volume size reduction may cause application issues — IOPS provisioning is the variable to optimize.' } },
  { id: 'd4-sto-008', domain: 4, topics: ['S3', 'versioning', 'cost'], type: 'single', stem: 'S3 versioning is enabled on a bucket where files are frequently overwritten. Old versions accumulate and increase storage costs. How can old version storage costs be controlled?', options: [{ id: 'A', text: 'Disable versioning' }, { id: 'B', text: 'S3 Lifecycle policy with NoncurrentVersionExpiration — automatically delete noncurrent versions after N days; retains only current version (and optionally N most recent versions)' }, { id: 'C', text: 'Move old versions to Glacier' }, { id: 'D', text: 'Manually delete old versions periodically' }], correct: ['B'], explanation: 'NoncurrentVersionExpiration lifecycle rule deletes old (noncurrent) object versions after a specified number of days. Retains only current version in hot storage. This maintains versioning benefits (recoverability) while preventing unbounded storage growth from old versions.', distractors: { A: 'Disabling versioning doesn\'t delete existing old versions — and loses the accidental deletion protection.', C: 'Moving to Glacier reduces cost per GB — NoncurrentVersionExpiration eliminates the cost entirely.', D: 'Manual deletion doesn\'t scale for millions of objects.' } },
  { id: 'd4-sto-009', domain: 4, topics: ['EFS', 'cost', 'lifecycle'], type: 'single', stem: 'An EFS filesystem stores files, 80% of which haven\'t been accessed in 90+ days. EFS Standard costs $0.30/GB/month. What reduces cost for infrequently accessed files?', options: [{ id: 'A', text: 'Delete unused files' }, { id: 'B', text: 'Enable EFS Intelligent-Tiering or lifecycle management — automatically moves files to EFS-IA ($0.025/GB/month) after 30/60/90 days of no access; 92% cheaper' }, { id: 'C', text: 'Use S3 instead of EFS' }, { id: 'D', text: 'Switch to FSx for Windows File Server' }], correct: ['B'], explanation: 'EFS Intelligent-Tiering lifecycle management moves files that haven\'t been accessed for 7/14/30/60/90 days to EFS-IA storage class ($0.025/GB/month vs $0.30/GB). 80% of cold files moving to IA reduces costs significantly. Files are transparently accessible — same POSIX API.', distractors: { A: 'Deleting files eliminates data — lifecycle management reduces cost without data loss.', C: 'S3 doesn\'t provide POSIX filesystem semantics — applications expecting EFS would need to be rewritten.', D: 'FSx for Windows is for SMB/Windows environments — different use case from EFS.' } },
  { id: 'd4-sto-010', domain: 4, topics: ['S3', 'requester pays', 'data access billing'], type: 'single', stem: 'A company hosts a large public dataset in S3. Data retrieval by external users generates significant S3 egress charges ($0.09/GB) for the data owner. What S3 feature shifts egress costs to the requester?', options: [{ id: 'A', text: 'S3 Transfer Acceleration' }, { id: 'B', text: 'S3 Requester Pays — requester pays the S3 data transfer and request charges; the bucket owner pays only for storage' }, { id: 'C', text: 'CloudFront to cache and reduce origin requests' }, { id: 'D', text: 'S3 Outposts' }], correct: ['B'], explanation: 'S3 Requester Pays configuration shifts S3 data transfer and request costs from the bucket owner to the requester. Requesters must be authenticated AWS users (anonymous access disabled). Ideal for public datasets, research data sharing, or B2B data distribution.', distractors: { A: 'Transfer Acceleration uses edge locations for faster uploads — doesn\'t change who pays for egress.', C: 'CloudFront caches content at edges — reduces origin requests but owner still pays for CloudFront egress.', D: 'S3 Outposts runs S3 on-premises — doesn\'t address internet egress cost model.' } },
  { id: 'd4-sto-011', domain: 4, topics: ['S3', 'multipart upload', 'abort'], type: 'single', stem: 'Failed multipart uploads leave partially uploaded parts in S3. These incomplete parts incur storage charges but are never combined into complete objects. How are these costs eliminated automatically?', options: [{ id: 'A', text: 'S3 auto-deletes incomplete multipart uploads' }, { id: 'B', text: 'S3 Lifecycle rule with AbortIncompleteMultipartUpload action — deletes incomplete uploads after N days; eliminates orphaned part storage' }, { id: 'C', text: 'Set a maximum upload timeout in the application' }, { id: 'D', text: 'Use S3 event notifications to detect failures' }], correct: ['B'], explanation: 'The AbortIncompleteMultipartUpload lifecycle action deletes incomplete multipart uploads after N days. This is a low-visibility but real S3 cost leak in active upload environments. AWS recommends enabling this rule as a best practice.', distractors: { A: 'S3 does NOT auto-delete incomplete multipart uploads — they accumulate until explicitly deleted or lifecycle rules run.', C: 'Application-side timeout may abort the upload client-side — doesn\'t delete the already-uploaded parts on S3.', D: 'Event notifications can detect events but a lifecycle rule is simpler for automatic cleanup.' } },
  { id: 'd4-sto-012', domain: 4, topics: ['EBS', 'Snapshot Archive', 'cost'], type: 'single', stem: 'EBS snapshots are rarely accessed (used only for annual DR testing) but must be retained for compliance. EBS snapshot standard storage costs $0.05/GB/month. What reduces snapshot storage cost for rarely-accessed archives?', options: [{ id: 'A', text: 'Delete old snapshots' }, { id: 'B', text: 'EBS Snapshot Archive — move snapshots to archive tier at $0.0125/GB/month (75% cheaper); restore to standard before use (24-72 hour restore)' }, { id: 'C', text: 'Export snapshots to S3 Glacier' }, { id: 'D', text: 'Use EC2 AMIs instead of snapshots' }], correct: ['B'], explanation: 'EBS Snapshot Archive tier stores snapshots at $0.0125/GB/month vs $0.05/GB/month standard — 75% savings. Restoring from archive takes 24-72 hours (moves back to standard tier). Ideal for compliance snapshots that are rarely but potentially needed.', distractors: { A: 'Deleting snapshots loses DR capability — Archive preserves them at lower cost.', C: 'EBS snapshots can\'t be moved to S3 Glacier directly — EBS Snapshot Archive is the AWS-native archiving solution.', D: 'AMIs contain snapshots — they have the same storage costs and are a different product.' } },
  { id: 'd4-sto-013', domain: 4, topics: ['S3', 'One Zone-IA', 'use cases'], type: 'single', stem: 'A media company stores thumbnail images that are easily regenerated from original files. Images are accessed infrequently. What S3 storage class provides the cheapest option for easily reproducible infrequent-access data?', options: [{ id: 'A', text: 'S3 Standard-IA (3-AZ)' }, { id: 'B', text: 'S3 One Zone-IA — stores data in a single AZ; 20% cheaper than Standard-IA; appropriate for data that can be recreated if the AZ fails' }, { id: 'C', text: 'S3 Glacier Flexible Retrieval' }, { id: 'D', text: 'S3 Intelligent-Tiering' }], correct: ['B'], explanation: 'S3 One Zone-IA: $0.01/GB/month vs Standard-IA $0.0125/GB/month. Stores in one AZ — if that AZ fails, data is lost. Acceptable for thumbnails, caches, transcoded media, and secondary backups that can be regenerated. Not appropriate for primary backups or compliance data.', distractors: { A: 'Standard-IA provides 3-AZ durability — costlier than One Zone-IA for easily reproducible data.', C: 'Glacier requires restore before access — not appropriate for infrequent but sometimes-needed thumbnails.', D: 'Intelligent-Tiering charges a monitoring fee ($0.0025/1,000 objects) — for known infrequent access, One Zone-IA is simpler and cheaper.' } },
  { id: 'd4-sto-014', domain: 4, topics: ['S3', 'storage lens', 'cost visibility'], type: 'single', stem: 'A company has 500 S3 buckets across 10 AWS accounts and needs visibility into storage trends, unused buckets, and cost optimization opportunities. What provides organization-wide S3 analytics?', options: [{ id: 'A', text: 'Check each bucket individually' }, { id: 'B', text: 'Amazon S3 Storage Lens — organization-wide S3 metrics dashboard with recommendations for cost optimization and data protection' }, { id: 'C', text: 'AWS Cost Explorer S3 costs' }, { id: 'D', text: 'CloudWatch S3 metrics' }], correct: ['B'], explanation: 'S3 Storage Lens provides 60+ usage and activity metrics aggregated across all S3 buckets in an organization. Default free dashboard includes 14-day metrics. Paid tier adds additional metrics, prefix-level data, and cost recommendations (e.g., identifying overprovisioned buckets, unused buckets, objects without lifecycle rules).', distractors: { A: 'Manual per-bucket analysis doesn\'t scale to 500 buckets across 10 accounts.', C: 'Cost Explorer shows S3 spend by account/service — Storage Lens provides S3-specific usage details and optimization recommendations.', D: 'CloudWatch S3 metrics show request-level metrics — not the cost optimization analysis and org-wide view of Storage Lens.' } },
  { id: 'd4-sto-015', domain: 4, topics: ['S3', 'data transfer', 'egress'], type: 'single', stem: 'A company streams video from S3 directly to users worldwide. Monthly S3 egress charges for 100 TB are $0.09/GB × 102,400 GB = $9,216. What reduces these egress costs?', options: [{ id: 'A', text: 'Use S3 Transfer Acceleration' }, { id: 'B', text: 'Put CloudFront in front of S3 — CloudFront caches content at edges; S3 egress to CloudFront is $0.00/GB for most transfers; CloudFront charges lower rates for end-user delivery' }, { id: 'C', text: 'Use S3 Cross-Region Replication to all regions' }, { id: 'D', text: 'Use S3 Select to reduce data transferred' }], correct: ['B'], explanation: 'CloudFront as an S3 CDN eliminates S3-to-CloudFront egress costs (free). CloudFront-to-end-user pricing (~$0.01-0.085/GB depending on region) is lower than direct S3 egress. For popular content, CloudFront cache hits eliminate S3 requests entirely. Reduces both egress costs and S3 request costs.', distractors: { A: 'Transfer Acceleration uses CloudFront edges for faster uploads — doesn\'t reduce download egress costs.', C: 'CRR copies data to multiple regions — increases storage cost without reducing per-download egress.', D: 'S3 Select reduces data scanned for queries — not relevant for video streaming.' } },
  { id: 'd4-sto-016', domain: 4, topics: ['EBS', 'cold storage', 'HDD'], type: 'single', stem: 'A big data cluster performs sequential reads of large log files for batch processing. Random IOPS performance is not required. What EBS volume type minimizes cost for sequential throughput workloads?', options: [{ id: 'A', text: 'gp3 (SSD)' }, { id: 'B', text: 'st1 (Throughput Optimized HDD) — $0.045/GB/month; optimized for large sequential reads; up to 500 MB/s throughput; 40x cheaper per GB than io2' }, { id: 'C', text: 'io2 Block Express' }, { id: 'D', text: 'sc1 (Cold HDD)' }], correct: ['B'], explanation: 'st1 HDD: $0.045/GB/month vs gp3 $0.08/GB/month. Optimized for sequential throughput (Hadoop, Kafka, log processing). Cannot be boot volume. For batch log processing with large sequential reads, st1 provides lower cost with sufficient throughput performance.', distractors: { A: 'gp3 is SSD — more expensive and designed for random I/O; unnecessary for sequential batch workloads.', C: 'io2 Block Express is high-performance SSD for demanding IOPS workloads — 10x more expensive than st1.', D: 'sc1 (Cold HDD) is cheaper ($0.015/GB) but maximum throughput is only 250 MB/s — st1 provides 500 MB/s for active big data workloads.' } },
  { id: 'd4-sto-017', domain: 4, topics: ['S3', 'request costs', 'optimization'], type: 'single', stem: 'An application makes millions of S3 GET requests daily to read small configuration files (few KBs). Each request costs $0.0004/1,000. Monthly request costs exceed storage costs. What reduces request costs?', options: [{ id: 'A', text: 'Use S3 Select to reduce data transferred' }, { id: 'B', text: 'Cache S3 objects in ElastiCache or application memory — read once from S3, serve from cache; dramatically reduces S3 request volume' }, { id: 'C', text: 'Move data to DynamoDB' }, { id: 'D', text: 'Use S3 batch operations' }], correct: ['B'], explanation: 'For frequently read, rarely changed objects (config files), application-level or ElastiCache caching reduces S3 GET requests by 99%+. Load config at startup or cache with TTL. Also consider Parameter Store or Secrets Manager for configuration data.', distractors: { A: 'S3 Select is for filtering large objects — not small configuration files where the entire file is needed.', C: 'DynamoDB has its own request pricing — doesn\'t inherently solve the request cost issue.', D: 'S3 Batch Operations processes large-scale S3 operations — not relevant for reducing read request frequency.' } },
  { id: 'd4-sto-018', domain: 4, topics: ['S3', 'Glacier Instant Retrieval', 'quarterly access'], type: 'single', stem: 'Medical records accessed approximately once per quarter must be immediately available (milliseconds) when requested. S3 Standard is too expensive for quarterly-accessed data. What provides instant access at Glacier-level pricing?', options: [{ id: 'A', text: 'S3 Glacier Flexible Retrieval (3-5 hours)' }, { id: 'B', text: 'S3 Glacier Instant Retrieval — millisecond access like Standard-IA but at Glacier pricing ($0.004/GB); designed for quarterly-accessed archives needing instant access' }, { id: 'C', text: 'S3 Standard-IA (higher cost)' }, { id: 'D', text: 'S3 Intelligent-Tiering Archive Instant Access tier' }], correct: ['B'], explanation: 'S3 Glacier Instant Retrieval: $0.004/GB/month with millisecond retrieval. Designed for archive data accessed once per quarter. Same retrieval latency as S3-IA but 68% cheaper than S3-IA ($0.0125/GB). 128 KB minimum object size; 90-day minimum storage period.', distractors: { A: 'Glacier Flexible Retrieval takes 3-5 hours — not appropriate for "immediately available when requested" medical records.', C: 'S3-IA ($0.0125/GB) is more expensive than Glacier Instant Retrieval ($0.004/GB) for the same millisecond access.', D: 'Intelligent-Tiering Archive Instant Access tier is the same underlying storage — Glacier Instant Retrieval is the direct product.' } },
  { id: 'd4-sto-019', domain: 4, topics: ['EBS', 'unattached volumes', 'waste'], type: 'single', stem: 'An audit reveals 200 EBS volumes that are unattached (no EC2 instance is using them). EBS charges apply even for unattached volumes. What is the cost optimization action?', options: [{ id: 'A', text: 'Leave them — storage cost is minimal' }, { id: 'B', text: 'Snapshot then delete unattached EBS volumes — EBS snapshots (in S3) cost 10-20x less than EBS volumes; snapshots can restore volumes if needed later' }, { id: 'C', text: 'Attach volumes to any running instance' }, { id: 'D', text: 'Convert EBS volumes to EFS' }], correct: ['B'], explanation: 'Unattached EBS volumes incur full volume charges ($0.08/GB for gp3). Solution: snapshot the volumes (preserves data at $0.05/GB), then delete the EBS volumes. If the volume is needed later, restore from snapshot. Use AWS Trusted Advisor to identify unattached volumes.', distractors: { A: '200 volumes of 100 GB each = 20 TB × $0.08/GB = $1,600/month — not minimal.', C: 'Attaching unused volumes to instances doesn\'t eliminate the cost.', D: 'EFS is a filesystem service — EBS volumes cannot be directly converted to EFS.' } },
  { id: 'd4-sto-020', domain: 4, topics: ['S3', 'data redundancy', 'One Zone vs Standard'], type: 'single', stem: 'A company replicates on-premises backups to S3 for disaster recovery. The on-premises copy is the primary. If AWS loses the S3 data (AZ failure in S3 One Zone-IA), the on-premises copy provides recovery. Is S3 One Zone-IA appropriate?', options: [{ id: 'A', text: 'No — S3 One Zone-IA is too risky for any backup data' }, { id: 'B', text: 'Yes — since the on-premises copy is primary and S3 is secondary, losing the One Zone-IA data is acceptable; saves 20% vs Standard-IA' }, { id: 'C', text: 'Use S3 Standard for all backup data regardless' }, { id: 'D', text: 'Use Glacier instead — cheaper' }], correct: ['B'], explanation: 'S3 One Zone-IA is appropriate when: (1) data can be recreated, or (2) another copy exists. When on-premises is the primary source, S3 One Zone-IA for secondary backup is acceptable and saves money. The risk (AZ failure) is mitigated by the primary copy.', distractors: { A: 'One Zone-IA is appropriate for reproducible or secondary data — risk tolerance depends on data protection architecture.', C: 'S3 Standard for backups is overly conservative and more expensive when a primary copy exists elsewhere.', D: 'Glacier requires restore time before use — may not meet DR RTO requirements for fast recovery.' } },
  { id: 'd4-sto-021', domain: 4, topics: ['FSx', 'Lustre', 'cost'], type: 'single', stem: 'An HPC workload uses FSx for Lustre scratch storage for temporary computation files. The computation runs for 72 hours. Scratch storage (SSD) is charged per GB-month. What reduces cost for temporary files?', options: [{ id: 'A', text: 'Use FSx Lustre persistent deployment type' }, { id: 'B', text: 'FSx for Lustre scratch deployment type — no data replication; lower cost than persistent; delete the filesystem after the 72-hour computation completes' }, { id: 'C', text: 'Store temporary files in S3 during computation' }, { id: 'D', text: 'Use EFS for HPC scratch storage' }], correct: ['B'], explanation: 'FSx Lustre scratch filesystems are optimized for temporary, burst workloads. They are cheaper than persistent and don\'t replicate data. For a 72-hour computation, create a scratch filesystem, run the job, then delete it. Pay only for 3 days of storage.', distractors: { A: 'Persistent deployment provides HA replication and SLA — more expensive and unnecessary for temporary computation.', C: 'S3 has high latency for many small random reads — FSx Lustre provides NFS-compatible high-performance scratch storage.', D: 'EFS has higher latency than Lustre for HPC workloads — FSx Lustre is purpose-built for HPC scratch.' } },
  { id: 'd4-sto-022', domain: 4, topics: ['S3', 'storage class analysis', 'right-sizing'], type: 'single', stem: 'A company has existing S3 objects and wants data-driven insights on which objects should move to cheaper storage classes. What S3 feature provides access frequency analysis?', options: [{ id: 'A', text: 'S3 inventory reports' }, { id: 'B', text: 'S3 Storage Class Analysis — analyzes access patterns over 30+ days and provides recommendations for when to transition objects to S3-IA; output can be used to configure lifecycle policies' }, { id: 'C', text: 'AWS Cost Explorer S3 analysis' }, { id: 'D', text: 'Amazon Macie' }], correct: ['B'], explanation: 'S3 Storage Class Analysis (Amazon S3 Analytics) monitors object-level access patterns per bucket or prefix. After 30+ days of analysis, it shows which object ages and access frequencies map to different storage tiers and provides specific lifecycle rule recommendations.', distractors: { A: 'S3 Inventory lists objects and their metadata — doesn\'t provide access frequency analysis.', C: 'Cost Explorer shows S3 spend — doesn\'t analyze per-object access patterns.', D: 'Amazon Macie identifies sensitive data — not a storage class optimization tool.' } },
  { id: 'd4-sto-023', domain: 4, topics: ['S3', 'minimum storage duration', 'cost'], type: 'single', stem: 'An object is uploaded to S3 Glacier Flexible Retrieval and deleted after 30 days. What is the minimum storage charge?', options: [{ id: 'A', text: 'Charged only for 30 days used' }, { id: 'B', text: 'Charged for 90 days minimum — Glacier Flexible Retrieval has a 90-day minimum storage period; deleting at 30 days still incurs 90-day charge' }, { id: 'C', text: 'Charged for 6 months minimum' }, { id: 'D', text: 'Glacier has no minimum storage period' }], correct: ['B'], explanation: 'Storage class minimum storage periods: Glacier Flexible Retrieval = 90 days, Glacier Deep Archive = 180 days, S3-IA = 30 days, S3 Glacier Instant Retrieval = 90 days. Deleting before the minimum incurs a prorated charge for the remaining minimum period. Objects should stay through their minimum period to avoid early deletion fees.', distractors: { A: '30 days is below the 90-day minimum — the remaining 60 days are charged as an early deletion penalty.', C: '6 months is the minimum for Glacier Deep Archive — not Flexible Retrieval.', D: 'All Glacier tiers and S3-IA have minimum storage periods — this is a key exam concept.' } },
  { id: 'd4-sto-024', domain: 4, topics: ['EBS', 'gp2 to gp3', 'migration'], type: 'single', stem: 'A company has 1,000 gp2 EBS volumes. AWS released gp3 at $0.08/GB (vs gp2 $0.10/GB) with better performance. What is the cost optimization?', options: [{ id: 'A', text: 'Wait for AWS to auto-migrate gp2 to gp3' }, { id: 'B', text: 'Migrate gp2 volumes to gp3 using Elastic Volumes (live modification — no downtime); 20% cost savings + decoupled IOPS/throughput tuning' }, { id: 'C', text: 'Recreate volumes with gp3 type' }, { id: 'D', text: 'gp2 and gp3 cost the same' }], correct: ['B'], explanation: 'EBS Elastic Volumes allows live modification of volume type, size, IOPS, and throughput without downtime or detaching. Modifying 1,000 gp2 volumes to gp3 can be scripted via AWS CLI. gp3 is 20% cheaper and decouples IOPS from size (gp2 IOPS scale with size; gp3 you choose independently).', distractors: { A: 'AWS does not auto-migrate gp2 to gp3 — customer must initiate.', C: 'Recreating volumes requires detaching, creating new, copying data, attaching — causes downtime; Elastic Volumes is non-disruptive.', D: 'gp3 ($0.08) is explicitly cheaper than gp2 ($0.10) — migrating provides real savings.' } },
  { id: 'd4-sto-025', domain: 4, topics: ['S3', 'cross-region replication', 'cost'], type: 'single', stem: 'A company uses S3 Cross-Region Replication (CRR) from us-east-1 to eu-west-1. What costs are incurred for CRR?', options: [{ id: 'A', text: 'CRR is free — AWS handles replication' }, { id: 'B', text: 'CRR charges: inter-region data transfer per GB, S3 PUT requests for replicated objects, and destination bucket storage costs' }, { id: 'C', text: 'Only destination storage costs' }, { id: 'D', text: 'Only source bucket charges' }], correct: ['B'], explanation: 'CRR cost components: (1) Inter-region data transfer: ~$0.02/GB from us-east-1 to eu-west-1, (2) S3 PUT requests in destination bucket, (3) Storage costs in destination bucket (same as normal S3 storage). Source bucket storage and source request costs are also normal.', distractors: { A: 'CRR is not free — data transfer costs are a significant consideration.', C: 'Data transfer is typically the largest CRR cost component — not just destination storage.', D: 'Source bucket charges are normal S3 costs — CRR adds destination storage and data transfer on top.' } },
  { id: 'd4-sto-026', domain: 4, topics: ['S3', 'access patterns', 'metrics'], type: 'single', stem: 'Before configuring S3 lifecycle policies, a team wants to understand how much data exists in each storage class and the total storage cost per bucket. What provides this inventory and cost data?', options: [{ id: 'A', text: 'AWS Config S3 tracking' }, { id: 'B', text: 'S3 Inventory reports (CSV/ORC/Parquet) — daily or weekly list of all objects with storage class, size, last modified; query with Athena for analysis' }, { id: 'C', text: 'CloudTrail S3 API logs' }, { id: 'D', text: 'S3 access logs' }], correct: ['B'], explanation: 'S3 Inventory provides scheduled reports (daily or weekly) of all objects: key, size, last modified date, storage class, replication status, encryption status. Output to S3 as CSV/ORC/Parquet. Query with Athena to identify large old objects in expensive storage classes.', distractors: { A: 'AWS Config tracks bucket-level configuration changes — not per-object storage class inventory.', C: 'CloudTrail logs API calls — not a per-object storage class report.', D: 'S3 access logs record request activity — not storage class inventory.' } },
  { id: 'd4-sto-027', domain: 4, topics: ['EBS', 'provisioned IOPS waste', 'monitoring'], type: 'single', stem: 'An io2 volume is provisioned for 20,000 IOPS but CloudWatch VolumeConsumedReadWriteOps shows only 5,000 average IOPS consumed. What is the over-provisioning ratio and cost implication?', options: [{ id: 'A', text: '25% utilized; no cost impact since IOPS are pre-paid' }, { id: 'B', text: '25% utilized; 15,000 unused IOPS are charged but wasted — reducing to 5,000-6,000 IOPS saves ~75% on IOPS charges' }, { id: 'C', text: 'AWS auto-adjusts provisioned IOPS to actual usage' }, { id: 'D', text: 'IOPS charges stop when not consumed' }], correct: ['B'], explanation: 'io2 charges $0.065/provisioned IOPS/month regardless of actual consumption. 20,000 IOPS × $0.065 = $1,300/month in IOPS charges. Reducing to 6,000 IOPS = $390/month — 70% savings. Use EBS Elastic Volumes to modify IOPS without downtime.', distractors: { A: 'IOPS are charged on provisioned amount — idle provisioned IOPS are wasted money.', C: 'AWS does not auto-adjust provisioned IOPS — customer manages this.', D: 'EBS charges are always on provisioned values — actual consumption doesn\'t affect the bill.' } },
  { id: 'd4-sto-028', domain: 4, topics: ['S3', 'batch operations', 'lifecycle'], type: 'single', stem: 'Millions of existing S3 objects predate lifecycle policies. A new lifecycle policy will move objects to Glacier going forward, but existing objects are stuck in Standard. What moves existing objects in bulk?', options: [{ id: 'A', text: 'Wait for lifecycle policy to process all objects (may take days)' }, { id: 'B', text: 'S3 Batch Operations — apply S3 operations (COPY, RESTORE, set ACL, add tags) to billions of existing objects using S3 Inventory as input' }, { id: 'C', text: 'Lambda function to iterate through objects' }, { id: 'D', text: 'Recreate lifecycle policy with retroactive flag' }], correct: ['B'], explanation: 'S3 Batch Operations can execute actions on billions of existing objects. Use a manifest (from S3 Inventory) listing objects to transition. Apply the Transition storage class operation. Processes millions of objects per minute — far faster than Lambda iteration.', distractors: { A: 'Lifecycle policies only apply to objects added after the rule is created (or on next evaluation for existing objects under the rule conditions).', C: 'Lambda iteration at scale (billions of objects) is slow, expensive in compute, and risks rate limiting.', D: 'Lifecycle policies don\'t have a retroactive flag — Batch Operations is the correct tool.' } },
  { id: 'd4-sto-029', domain: 4, topics: ['S3', 'delete markers', 'cleanup'], type: 'single', stem: 'A versioned S3 bucket accumulates delete markers from deleted objects. These delete markers don\'t contain data but count in object count limits and list operations. How are delete markers cleaned up at scale?', options: [{ id: 'A', text: 'S3 automatically removes delete markers' }, { id: 'B', text: 'S3 Lifecycle rule with ExpiredObjectDeleteMarker action — removes delete markers that have no noncurrent versions (i.e., expired markers)' }, { id: 'C', text: 'S3 Batch Operations delete all markers manually' }, { id: 'D', text: 'Disable versioning to remove markers' }], correct: ['B'], explanation: 'The ExpiredObjectDeleteMarker lifecycle action removes delete markers that no longer have any associated noncurrent versions. Keeps the versioned bucket clean without manual intervention. Combine with NoncurrentVersionExpiration to fully manage versioned bucket storage.', distractors: { A: 'Delete markers accumulate without lifecycle rules — AWS doesn\'t auto-remove them.', C: 'S3 Batch Operations can delete objects — for automated ongoing cleanup, lifecycle rules are simpler.', D: 'Disabling versioning doesn\'t remove existing markers — and removes accidental deletion protection going forward.' } },
  { id: 'd4-sto-030', domain: 4, topics: ['S3', 'replication', 'SRR vs CRR'], type: 'single', stem: 'A company replicates S3 data within the same region (us-east-1) for compliance — data must exist in two separate accounts but same region. Is cross-region replication required?', options: [{ id: 'A', text: 'Yes — replication always requires different regions' }, { id: 'B', text: 'No — S3 Same-Region Replication (SRR) replicates within the same region across buckets and accounts; no cross-region data transfer charges' }, { id: 'C', text: 'Use CRR — SRR doesn\'t support cross-account' }, { id: 'D', text: 'Use S3 Batch Copy instead' }], correct: ['B'], explanation: 'Same-Region Replication (SRR) replicates within the same AWS region — including across different AWS accounts. No inter-region data transfer charges. Use cases: compliance copies in different accounts, aggregating logs from multiple accounts, or replicating to test environments.', distractors: { A: 'CRR is for cross-region; SRR handles same-region replication — choosing CRR when SRR suffices incurs unnecessary data transfer costs.', C: 'SRR does support cross-account replication within the same region.', D: 'S3 Batch Copy is for one-time bulk operations — SRR provides continuous real-time replication.' } },
  { id: 'd4-sto-031', domain: 4, topics: ['EBS', 'fast snapshot restore', 'cost'], type: 'single', stem: 'EBS Fast Snapshot Restore (FSR) eliminates the I/O performance penalty when restoring volumes from snapshots. What is the cost consideration for FSR?', options: [{ id: 'A', text: 'FSR is free — included with EBS' }, { id: 'B', text: 'FSR charges $0.75/DSU (Direct Snapshot Usage) per AZ; enabling FSR on large snapshots across many AZs can be expensive — only enable for frequently used snapshots' }, { id: 'C', text: 'FSR increases the snapshot storage cost' }, { id: 'D', text: 'FSR requires a separate SSD tier' }], correct: ['B'], explanation: 'Fast Snapshot Restore is charged per DSU (Direct Snapshot Usage) per AZ per hour. DSU = 1 for <16 TiB snapshots, scales proportionally for larger. Enabling FSR across many AZs for rarely restored snapshots adds cost without proportional benefit. Enable only for snapshots that are frequently used for recovery or launch.', distractors: { A: 'FSR has explicit per-AZ per-hour charges — it is not free.', C: 'FSR doesn\'t change snapshot storage cost — it\'s a separate activation fee for fast restore capability.', D: 'FSR works with standard EBS snapshots — no separate storage tier.' } },
  { id: 'd4-sto-032', domain: 4, topics: ['S3', 'server access logging', 'costs'], type: 'single', stem: 'S3 server access logging is enabled on a high-traffic bucket. Log files accumulate indefinitely in the log bucket and the log bucket itself generates more logs (recursive). What prevents unbounded log storage costs?', options: [{ id: 'A', text: 'Disable S3 server access logging' }, { id: 'B', text: 'Point access logs to a separate log bucket (not the source bucket) and add a lifecycle rule to delete logs after N days' }, { id: 'C', text: 'Use CloudTrail instead of S3 access logging' }, { id: 'D', text: 'Compress log files daily' }], correct: ['B'], explanation: 'Best practices: (1) log to a separate bucket (the log bucket should not have logging enabled — prevents recursion), (2) lifecycle rule to expire logs after 30-90 days depending on retention needs. Access logs themselves are S3 objects charged at standard rates.', distractors: { A: 'Disabling logging removes audit capability.', C: 'CloudTrail is for API-level logging (who called what API) — S3 access logging captures every GET/PUT request to objects; both may be needed for different purposes.', D: 'Compression reduces file size — doesn\'t prevent indefinite accumulation.' } },
  { id: 'd4-sto-033', domain: 4, topics: ['Storage Gateway', 'Tape Gateway', 'cost'], type: 'single', stem: 'A company uses physical tape libraries for backups costing $50,000/year in hardware and maintenance. What AWS service virtualizes tape backups to reduce costs?', options: [{ id: 'A', text: 'AWS Snowball Edge' }, { id: 'B', text: 'AWS Storage Gateway Tape Gateway — presents a virtual tape library to backup software; stores virtual tapes in S3 (active) and Glacier (archived); eliminates physical tape hardware' }, { id: 'C', text: 'AWS Backup' }, { id: 'D', text: 'Amazon S3 Glacier direct API' }], correct: ['B'], explanation: 'Tape Gateway creates Virtual Tape Library (VTL) — virtual tape cartridges and tape drives compatible with existing backup software (Veeam, NetBackup, Backup Exec). Active tapes in S3; archived in Glacier. Eliminates physical tape hardware, shipping costs, and offsite storage fees.', distractors: { A: 'Snowball Edge is for physical data transfer/edge compute — not virtual tape library replacement.', C: 'AWS Backup is a centralized backup management service — doesn\'t provide VTL interface for existing backup software.', D: 'Direct Glacier API requires modifying backup application code — Tape Gateway is transparent to existing backup software.' } },
  { id: 'd4-sto-034', domain: 4, topics: ['EFS', 'Throughput modes', 'bursting vs provisioned'], type: 'single', stem: 'An EFS filesystem has unpredictable throughput needs. During quiet periods, throughput is unused but during events it needs 500 MB/s. The filesystem stores 500 GB but needs 500 MB/s burst. EFS Bursting mode only allows 50 MB/s baseline for 500 GB. What provides guaranteed throughput regardless of storage size?', options: [{ id: 'A', text: 'EFS Bursting mode — scales with stored data' }, { id: 'B', text: 'EFS Elastic Throughput — automatically scales between 100 MB/s to 10 GB/s based on workload; pay for what you use; no need to provision' }, { id: 'C', text: 'EFS Provisioned Throughput at 500 MB/s — fixed cost regardless of actual use' }, { id: 'D', text: 'Move to FSx for Lustre for high throughput' }], correct: ['B'], explanation: 'EFS Elastic Throughput automatically scales throughput (up to 3 GB/s read, 1 GB/s write) based on actual demand. No over-provisioning for peaks. Pay per GB transferred ($0.03/GB). Ideal for spiky throughput needs where the filesystem size doesn\'t correlate to throughput requirements.', distractors: { A: 'EFS Bursting provides throughput proportional to stored data — insufficient for 500 MB/s with only 500 GB stored.', C: 'EFS Provisioned Throughput ($6/MB/s provisioned/month) guarantees throughput but charges for unused capacity during quiet periods.', D: 'FSx Lustre is higher performance but requires a different filesystem — more disruptive migration.' } },
  { id: 'd4-sto-035', domain: 4, topics: ['S3', 'data retrieval', 'Glacier restore'], type: 'single', stem: 'Objects restored from S3 Glacier Flexible Retrieval appear as temporary S3 Standard copies. After restoration, if the restored copy is not deleted, what charges occur?', options: [{ id: 'A', text: 'No additional charges after Glacier restore' }, { id: 'B', text: 'S3 Standard storage charges for the restored copy accumulate daily; Glacier copy still charges Glacier rates; both are billed until the restored copy expires or is deleted' }, { id: 'C', text: 'Glacier copy is deleted automatically when restored' }, { id: 'D', text: 'Only the restore request charge; no ongoing charges' }], correct: ['B'], explanation: 'Glacier restore creates a temporary Standard copy. This copy incurs Standard storage charges per day until it expires (1-365 day expiration specified at restore time). The original Glacier object remains and continues incurring Glacier charges. Set the minimum restore period needed to avoid double-charging.', distractors: { A: 'The temporary Standard copy charges accumulate until it expires.', C: 'The original Glacier copy is preserved — only the temporary Standard copy is created on restore.', D: 'Restore has request charges plus per-GB retrieval charges — and then ongoing Standard storage charges for the temporary copy.' } },
  { id: 'd4-sto-036', domain: 4, topics: ['S3', 'cost per request type', 'tiering'], type: 'single', stem: 'Moving objects from S3 Standard to S3 Standard-IA via lifecycle policy incurs transition request charges. For a 1 KB object, the monthly Standard-IA storage savings is tiny. What minimum object size makes S3-IA economically sensible?', options: [{ id: 'A', text: 'Any size — S3-IA is always cheaper' }, { id: 'B', text: 'S3-IA has a 128 KB minimum billable size — objects smaller than 128 KB are billed as 128 KB; only objects larger than 128 KB see cost benefits from IA' }, { id: 'C', text: 'Objects must be at least 1 MB' }, { id: 'D', text: 'Size doesn\'t matter — transitions are always beneficial' }], correct: ['B'], explanation: 'S3-IA minimum billing size is 128 KB. A 1 KB object stored in S3-IA is billed as 128 KB. At 1 KB actual storage, S3-IA costs 128x more per byte than claimed. For cost-effective tiering, only move objects > 128 KB (and ideally much larger) to S3-IA.', distractors: { A: 'For objects < 128 KB, S3-IA costs more than S3 Standard due to minimum billing.', C: '1 MB is a reasonable practical threshold for efficient tiering — the minimum is 128 KB.', D: 'Transition request charges and minimum size make small object transitions uneconomical.' } },
  { id: 'd4-sto-037', domain: 4, topics: ['S3', 'Outposts', 'on-premises'], type: 'single', stem: 'A company has applications on AWS Outposts that generate data needing low-latency local storage with the S3 API. They don\'t want data to leave the on-premises location. What S3 service provides on-premises S3 storage?', options: [{ id: 'A', text: 'S3 with VPN — low latency access' }, { id: 'B', text: 'Amazon S3 on Outposts — S3-compatible storage running on Outposts hardware; data stays on-premises; same S3 APIs and lifecycle management' }, { id: 'C', text: 'Storage Gateway File Gateway' }, { id: 'D', text: 'EFS with Direct Connect' }], correct: ['B'], explanation: 'S3 on Outposts runs the S3 service on Outposts hardware. Applications use standard S3 SDK/API. Data never leaves the Outposts — meets data residency requirements. Priced per GB of S3 on Outposts capacity.', distractors: { A: 'VPN reduces security risk but data still goes to AWS regions — doesn\'t keep data on-premises.', C: 'Storage Gateway File Gateway caches S3 data locally — the primary storage is in AWS S3, not on-premises.', D: 'EFS is a cloud service — data is in AWS, not on-premises Outposts.' } },
  { id: 'd4-sto-038', domain: 4, topics: ['S3', 'Macie', 'data security costs'], type: 'single', stem: 'A company discovers they are storing sensitive PII in S3 buckets but don\'t know which buckets or objects contain it. What service discovers and classifies sensitive data in S3?', options: [{ id: 'A', text: 'AWS Config S3 compliance rules' }, { id: 'B', text: 'Amazon Macie — uses ML to automatically discover, classify, and protect sensitive data (PII, PHI, financial data) in S3; generates findings for sensitive object locations' }, { id: 'C', text: 'Amazon GuardDuty' }, { id: 'D', text: 'AWS Security Hub' }], correct: ['B'], explanation: 'Amazon Macie scans S3 buckets and uses ML to classify sensitive data. Findings include: object location, data type (PII, credentials, financial), and violation severity. Priced per GB of S3 data scanned. Enables compliance and helps prevent accidental public exposure of sensitive data.', distractors: { A: 'AWS Config checks bucket configurations (public access, encryption) — not object-level content classification.', C: 'GuardDuty detects threats and unusual activity — not sensitive data classification in S3 objects.', D: 'Security Hub aggregates findings from multiple services — doesn\'t perform content scanning itself.' } },
  { id: 'd4-sto-039', domain: 4, topics: ['S3', 'versioning suspend', 'costs'], type: 'single', stem: 'Versioning is enabled on an S3 bucket but the team wants to stop accumulating new versions (keep existing). Disabling versioning completely removes versioning. What action stops new version accumulation without losing existing versions?', options: [{ id: 'A', text: 'Disable versioning — removes all existing versions' }, { id: 'B', text: 'Suspend versioning — new PUT operations don\'t create new versions; existing versions are preserved; null version IDs are used for new objects' }, { id: 'C', text: 'Create a lifecycle rule to delete all new versions immediately' }, { id: 'D', text: 'Move the bucket to S3-IA to reduce versioning costs' }], correct: ['B'], explanation: 'Suspending versioning preserves all existing versions (data protection maintained) but stops creating new versions for future PUTs. New objects get a null version ID. Existing versioned objects retain their version IDs. This is a middle ground between full versioning and disabling.', distractors: { A: 'Disabling versioning doesn\'t delete existing versions — but suspending is the correct way to stop new version creation.', C: 'Lifecycle rules deleting new versions adds complexity and delay — suspension is simpler.', D: 'Storage class changes don\'t affect versioning behavior.' } },
  { id: 'd4-sto-040', domain: 4, topics: ['EBS', 'multi-attach', 'cost'], type: 'single', stem: 'An application cluster shares a single EBS io2 volume mounted to 5 EC2 instances simultaneously. Is there an additional cost for EBS Multi-Attach?', options: [{ id: 'A', text: 'Yes — Multi-Attach adds a per-attachment charge' }, { id: 'B', text: 'No — EBS Multi-Attach has no additional charge; the io2 volume is charged at standard rates regardless of how many instances it\'s attached to' }, { id: 'C', text: 'Multi-Attach doubles the EBS cost' }, { id: 'D', text: 'Multi-Attach is only available as a premium feature with extra cost' }], correct: ['B'], explanation: 'EBS Multi-Attach allows a single io1/io2 volume to be attached to up to 16 EC2 instances simultaneously within the same AZ. There is no additional charge for Multi-Attach — the volume is charged at the standard io2 rate regardless of attachment count.', distractors: { A: 'Multi-Attach is a feature included with io1/io2 at no extra charge.', C: 'The volume cost remains the same regardless of attachment count.', D: 'Multi-Attach is a standard feature of io1/io2 — no premium tier required.' } },
  { id: 'd4-sto-041', domain: 4, topics: ['S3', 'inventory', 'Athena analysis'], type: 'single', stem: 'A company wants to identify all S3 objects larger than 5 GB to prioritize multipart upload migration and find objects in wrong storage classes. S3 Inventory outputs to S3 as CSV. How can this be analyzed efficiently?', options: [{ id: 'A', text: 'Download the CSV and analyze in Excel' }, { id: 'B', text: 'Use Amazon Athena to query S3 Inventory files with SQL — query billions of object records without moving data; filter by size, storage class, last modified date' }, { id: 'C', text: 'Use AWS Glue to process the inventory' }, { id: 'D', text: 'Use a Python script to read the CSV' }], correct: ['B'], explanation: 'S3 Inventory outputs ORC or Parquet files to S3. Create an Athena table pointing to the inventory location. SQL query: SELECT key, size, storageclass WHERE size > 5368709120 AND storageclass = \'STANDARD\'. Analyze terabytes of inventory data in seconds.', distractors: { A: 'Excel can\'t handle billion-row inventory files — Athena provides SQL-scale analysis.', C: 'Glue works but adds setup complexity — Athena is simpler for ad-hoc S3 Inventory analysis.', D: 'Python iteration is slow for large inventories and requires compute resources.' } },
  { id: 'd4-sto-042', domain: 4, topics: ['EBS', 'snapshot copy', 'cross-region cost'], type: 'single', stem: 'EBS snapshots are copied from us-east-1 to eu-west-1 for disaster recovery. What costs are incurred for cross-region snapshot copies?', options: [{ id: 'A', text: 'Only destination storage costs' }, { id: 'B', text: 'Cross-region data transfer costs (~$0.02/GB) + destination S3 storage costs; first copy is full; subsequent are incremental (only changed blocks)' }, { id: 'C', text: 'EBS snapshots copy for free cross-region' }, { id: 'D', text: 'Only the initial copy is charged; re-copies are free' }], correct: ['B'], explanation: 'Copying EBS snapshots cross-region incurs: (1) data transfer charges for the snapshot data crossing regions, (2) EBS snapshot storage in the destination region. First copy is full; subsequent copies are incremental (only changed blocks transfer). Plan DR snapshot frequency with cross-region transfer costs in mind.', distractors: { A: 'Inter-region data transfer is a significant cost component of cross-region snapshot copies.', C: 'Cross-region snapshot copies are not free — data transfer charges apply.', D: 'Each cross-region copy incurs data transfer charges for the data transferred (changed blocks for incremental copies).' } },
  { id: 'd4-sto-043', domain: 4, topics: ['S3', 'storage efficiency', 'compression'], type: 'single', stem: 'A data pipeline stores 10 TB of CSV files in S3 Standard. The CSV data is 70% compressible. Compression reduces storage to 3 TB and also reduces Athena scan costs. What is the monthly storage savings if S3 Standard costs $0.023/GB?', options: [{ id: 'A', text: '$0 — compression has overhead costs' }, { id: 'B', text: 'Approximately $160/month: 7 TB saved × $0.023/GB × 1,024 GB/TB; Athena scan costs also reduced 70%' }, { id: 'C', text: '$10/month — minimal savings' }, { id: 'D', text: 'Compression increases S3 costs' }], correct: ['B'], explanation: '7 TB × 1,024 GB × $0.023 ≈ $164/month in storage savings. Plus Athena scan savings (70% less data scanned). Use gzip or Snappy/Zstd for CSV/JSON; use Parquet/ORC for columnar + compression together. The combination of Parquet format + compression is the gold standard for data lake economics.', distractors: { A: 'Compression CPU cost is one-time at write time — storage savings are ongoing monthly.', C: '$10 underestimates — 7 TB × $0.023/GB/month is significant.', D: 'Compression reduces storage — it never increases S3 costs.' } },
  { id: 'd4-sto-044', domain: 4, topics: ['S3', 'data residency', 'region lock'], type: 'single', stem: 'EU data protection regulations require customer data to remain in Europe. S3 data by default stays in the configured region, but administrators could accidentally replicate data to US regions. What prevents data from leaving EU regions?', options: [{ id: 'A', text: 'S3 bucket policy denying replication' }, { id: 'B', text: 'AWS Organizations Service Control Policy (SCP) restricting S3 replication and actions to EU regions only; also AWS Resource Policies or S3 Object Lock can enforce residency' }, { id: 'C', text: 'S3 data stays in its region by default — no additional control needed' }, { id: 'D', text: 'CloudTrail to detect any cross-region replication' }], correct: ['B'], explanation: 'SCPs can deny s3:ReplicateObject to non-EU regions at the organization level. Also deny actions that could copy data (s3:CopyObject to non-EU destinations). This provides organization-wide enforcement that can\'t be overridden by account administrators.', distractors: { A: 'Bucket policies require consistent application across all buckets — SCPs enforce at organization level uniformly.', C: 'S3 data stays in its region by default but admins can create replication rules — SCP enforcement prevents accidental violations.', D: 'CloudTrail detects after the fact — SCPs prevent the action before it happens.' } },
  { id: 'd4-sto-045', domain: 4, topics: ['S3', 'cost calculator', 'total cost'], type: 'single', stem: 'A solution architect is comparing the total monthly cost of storing 100 TB in S3 Standard vs S3 Glacier Flexible Retrieval (assuming monthly retrieval of 1% = 1 TB). Which is cheaper, and what costs must be included for Glacier?', options: [{ id: 'A', text: 'S3 Standard is always cheaper due to lower retrieval overhead' }, { id: 'B', text: 'Glacier is cheaper: 100 TB × $0.004/GB ≈ $410/month storage + ~$10-20 for 1 TB retrieval vs Standard $0.023/GB ≈ $2,355/month — Glacier wins even with retrieval costs' }, { id: 'C', text: 'They cost the same' }, { id: 'D', text: 'Glacier is cheaper only if you never retrieve data' }], correct: ['B'], explanation: 'Glacier Flexible Retrieval storage (100 TB at $0.004/GB) = $409/month. Standard retrieval (1 TB at ~$0.01/GB) = ~$10. Total Glacier ≈ $420/month. S3 Standard (100 TB at $0.023/GB) = $2,355/month. Glacier is ~83% cheaper even with monthly retrievals. Include: storage, retrieval (per GB + per request), lifecycle transition costs.', distractors: { A: 'Standard is significantly more expensive at scale — Glacier retrieval costs don\'t offset the storage savings for typical access patterns.', C: 'Standard is 5x+ more expensive than Glacier at 100 TB scale.', D: 'Glacier is cheaper even with regular monthly retrievals at reasonable volumes.' } },
]
